<script setup lang="ts">
import {useTableWidths} from './tableWidths'
const widths=useTableWidths('WarehouseLabels')
import {ref,reactive,computed,watch} from 'vue'
import {api} from './session'
import {ElMessage} from 'element-plus'
const props=defineProps<{open:boolean}>(),emit=defineEmits(['close']),rows=ref<any[]>([]),selected=ref<any[]>([]),total=ref(0),stores=ref<string[]>([]),markets=ref<string[]>([]),busy=ref(false),error=ref('')
const filters=reactive({q:'',store:'',country:'',page:1,page_size:25}),form=reactive({separators:false,channel:'',date:new Date().toLocaleDateString('sv-SE')})
const identity=computed(()=>selected.value[0]),count=computed(()=>selected.value.reduce((s,r)=>s+Number(r.quantity||0),0))
async function load(){try{const d=await api('/settings/label-listings?'+new URLSearchParams({...filters,page:String(filters.page),page_size:String(filters.page_size)}));rows.value=d.rows;total.value=d.total}catch(e){error.value=(e as Error).message}}
watch(()=>props.open,async v=>{if(v){error.value='';selected.value=[];const o=await api('/options');stores.value=o.stores;markets.value=o.markets;await load()}})
function add(row:any){if(selected.value.some(r=>r.id===row.id))return;if(identity.value&&(identity.value.store!==row.store||identity.value.country!==row.country)){ElMessage.warning('无法同时打印两个不同国家或不同店铺的标签');return}if(!row.fnsku){ElMessage.warning('该商品缺少 FNSKU，请先同步库存');return}selected.value.push({...row,quantity:1})}
function toggle(row:any,on:boolean){if(on)add(row);else selected.value=selected.value.filter(r=>r.id!==row.id)}
async function print(){if(!selected.value.length)return;busy.value=true;error.value='';try{const r=await fetch('/api/settings/print-labels',{method:'POST',headers:{'Content-Type':'application/json','X-ERP-Client':'web'},body:JSON.stringify({...form,date:form.separators?form.date:null,items:selected.value.map(r=>({id:r.id,quantity:r.quantity}))})});if(!r.ok){const d=await r.json();throw Error(typeof d.detail==='string'?d.detail:'请检查标签数量和资料')}const url=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=url;a.download=`${identity.value.store}-${identity.value.country}-FNSKU标签.pdf`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);ElMessage.success('双排50×50mm标签已生成')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><el-dialog :model-value="open" title="打印 FNSKU 标签" width="min(1450px,97vw)" @close="emit('close')"><el-alert v-if="error" :title="error" type="error" :closable="false"/><div class="label-layout"><section><div class="label-filters"><el-input v-model="filters.q" placeholder="SKU / FNSKU / 标品编码 / 品名" @keyup.enter="filters.page=1;load()"/><el-select v-model="filters.store" clearable placeholder="店铺"><el-option v-for="s in stores" :value="s" :label="s"/></el-select><el-select v-model="filters.country" clearable placeholder="国家"><el-option v-for="m in markets" :value="m" :label="m"/></el-select><el-button @click="filters.page=1;load()">搜索</el-button><TableReset table-key="WarehouseLabels/table-1"/></div><template v-if="true"><el-table :data="rows" height="480" border data-width-key="WarehouseLabels/table-1" @header-dragend="(w:number,_:number,c:any)=>widths.resize('table-1',w,c)"><el-table-column column-key="c1" :width="widths.width('table-1','c1',45)" ><template #default="{row}"><el-checkbox :model-value="selected.some(r=>r.id===row.id)" :aria-label="'选择 '+row.sku" @change="(v:any)=>toggle(row,!!v)"/></template></el-table-column><el-table-column column-key="sku" :width="widths.width('table-1','sku',185)" prop="sku" label="SKU"/><el-table-column column-key="fnsku" :width="widths.width('table-1','fnsku',130)" label="FNSKU"><template #default="{row}">{{row.fnsku||'缺少 FNSKU'}}</template></el-table-column><el-table-column column-key="name" :width="widths.width('table-1','name',200)" prop="name" label="品名"/><el-table-column column-key="identity" :width="widths.width('table-1','identity',140)" label="店铺 / 国家"><template #default="{row}">{{row.store}} / {{row.country}}</template></el-table-column></el-table></template><AppPagination v-model:current-page="filters.page" :total="total" @change="load" v-model:page-size="filters.page_size"/></section><section class="label-selected"><div class="label-filters"><strong>已选 {{selected.length}} 款 / {{count}} 张</strong><el-checkbox v-model="form.separators">打印起止信息</el-checkbox><TableReset table-key="WarehouseLabels/table-2"/></div><div v-if="form.separators" class="label-filters"><el-input :model-value="identity?identity.store+' - '+identity.country:''" disabled placeholder="选择产品后带出店铺与国家"/><el-select v-model="form.channel" placeholder="渠道"><el-option label="空派" value="air"/><el-option label="卡航" value="truck"/><el-option label="海运" value="sea"/></el-select><el-date-picker v-model="form.date" value-format="YYYY-MM-DD"/></div><template v-if="true"><el-table :data="selected" height="420" border data-width-key="WarehouseLabels/table-2" @header-dragend="(w:number,_:number,c:any)=>widths.resize('table-2',w,c)"><el-table-column column-key="c1" :width="widths.width('table-2','c1',170)" prop="sku" label="SKU" min-width="170"/><el-table-column column-key="fnsku" :width="widths.width('table-2','fnsku',130)" prop="fnsku" label="FNSKU"/><el-table-column column-key="c2" :width="widths.width('table-2','c2',150)" label="数量"  align="center"><template #default="{row}"><el-input-number v-model="row.quantity" :min="1" :max="20000" :precision="0" :controls="false" style="width:120px"/></template></el-table-column><el-table-column column-key="c3" :width="widths.width('table-2','c3',70)" ><template #default="{row}"><el-button link type="danger" @click="toggle(row,false)">移除</el-button></template></el-table-column></el-table></template></section></div><template #footer><el-button @click="emit('close')">关闭</el-button><el-button type="primary" :loading="busy" :disabled="!selected.length" @click="print">打印</el-button></template></el-dialog></template>
<style scoped>.label-layout{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,1fr);gap:20px}.label-filters{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:12px}.label-filters>.el-input{width:240px}.label-filters>.el-select{width:120px}.label-selected{border:1px solid #e1ebe6;padding:14px}.label-layout :deep(td:first-child .cell){padding-left:8px;padding-right:8px}.label-layout>section{min-width:0}.label-selected :deep(.el-input-number){display:block;width:100%!important;max-width:120px}.label-layout small{color:#84968d}@media(max-width:1100px){.label-layout{grid-template-columns:minmax(0,1fr)}.label-selected{margin-top:8px}}</style>
